from PIL import Image
import numpy as np
rgb=np.array(Image.open('first_frame.png').convert('RGB'))
r,g,b=rgb[...,0],rgb[...,1],rgb[...,2]
criteria={
'r_gt120':r>120,
'orange1':(r>120)&(g>50)&(g<150)&(b<90)&(r>g+25)&(g>b+10),
'orange2':(r>140)&(g>80)&(g<160)&(b<80)&(r>g+20),
'orange3':(r>150)&(g>90)&(g<170)&(b<100),
'redshift':(r>g*1.25)&(g>b*1.15)&(r>100),
}
for name,m in criteria.items():
 ys,xs=np.where(m)
 print('\\n',name, m.sum())
 if len(xs): print('bbox',xs.min(),ys.min(),xs.max(),ys.max(),'mean',rgb[m].mean(0).round(1))
 # connected comps simple
 h,w=m.shape; seen=np.zeros_like(m,bool); comps=[]
 for sy,sx in zip(ys,xs):
  if seen[sy,sx]: continue
  stack=[(sy,sx)];seen[sy,sx]=1; pts=[]
  while stack:
   y,x=stack.pop();pts.append((y,x))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     ny,nx=y+dy,x+dx
     if 0<=ny<h and 0<=nx<w and m[ny,nx] and not seen[ny,nx]:
      seen[ny,nx]=1;stack.append((ny,nx))
  if len(pts)>10:
   yy=[p[0] for p in pts];xx=[p[1] for p in pts]
   comps.append((len(pts),(min(xx),min(yy),max(xx),max(yy)),rgb[pts].mean(0).round(1)))
 for z in sorted(comps,reverse=True)[:10]:print(z)
PY"

